// Gym v3 assets: design frames for the static-design POI and copy for the text POI (catalogue: gym/defects.yaml, poi design | text). Sources are in design.ts, regenerated by generate-assets.ts.
// gymAssets({ defects }): "all" (default) switches on every v3 defect (D26–D28), "none" is the control build, or a comma list of ids; web defects (D01–D25) are accepted and ignored, so one GYM_DEFECTS value can drive the server and the assets. Returns absolute paths: frames per sequence in order, and the copy files.
import { fileURLToPath } from "node:url";
import { DEFECT_IDS } from "./server.ts";

export const GYM_V3_DEFECT_IDS = ["D26", "D27", "D28"];
// Each sequence or copy sample has one defect; its other variant is "control".
export const FRAME_SEQUENCES = {
  checkout: { defect: "D26", frames: 6 }, // frame 4 is a sign-in prompt where an order confirmation is expected
  invite: { defect: "D27", frames: 4 }, // frame 2 has an icon-only Invite control with an abstract glyph
} as const;
export const COPY_SAMPLES = { pricing: { defect: "D28" } } as const; // the Team plan lists SSO, which the table and FAQ give to Business only

export const frameKey = (sequence: keyof typeof FRAME_SEQUENCES, variant: string, index: number) =>
  `frames/${sequence}/${variant}/${String(index + 1).padStart(2, "0")}.png`;
export const copyKey = (sample: keyof typeof COPY_SAMPLES, variant: string) => `copy/${sample}/${variant}.md`;
export const assetFile = (key: string) => fileURLToPath(new URL(`assets/${key}`, import.meta.url));

function parseDefects(spec: string): Set<string> {
  if (spec === "all") return new Set(GYM_V3_DEFECT_IDS);
  if (spec === "none") return new Set();
  const ids = spec.split(",").map((id) => id.trim()).filter(Boolean);
  const unknown = ids.find((id) => !GYM_V3_DEFECT_IDS.includes(id) && !DEFECT_IDS.includes(id));
  if (unknown) throw new Error(`Unknown defect ${unknown}`);
  return new Set(ids);
}

export function gymAssets(opts: { defects?: string } = {}) {
  const on = parseDefects(opts.defects ?? "all");
  const variant = (defect: string) => (on.has(defect) ? defect : "control");
  const frames = (sequence: keyof typeof FRAME_SEQUENCES) =>
    Array.from({ length: FRAME_SEQUENCES[sequence].frames }, (_, i) =>
      assetFile(frameKey(sequence, variant(FRAME_SEQUENCES[sequence].defect), i)));
  return {
    frames: { checkout: frames("checkout"), invite: frames("invite") },
    copy: { pricing: assetFile(copyKey("pricing", variant(COPY_SAMPLES.pricing.defect))) },
  };
}
